/**
 * Day-0 CALLING SPIKE (temporary screen).
 *
 * Goal: prove that LiveKit audio + video work inside our Expo dev build on a
 * real Android phone before we build any features around it.
 * The phone joins room "spike" with a token generated by
 * server/scripts/make_spike_tokens.py; the laptop joins the same room from a browser.
 *
 * This file is replaced by the real app (auth, tabs, call screens) on day 1.
 */
import { useEffect, useState } from 'react';
import { PermissionsAndroid, Platform, Pressable, StyleSheet, Text, View } from 'react-native';
import { StatusBar } from 'expo-status-bar';
import {
  AudioSession,
  LiveKitRoom,
  VideoTrack,
  isTrackReference,
  useConnectionState,
  useLocalParticipant,
  useRoomContext,
  useTracks,
} from '@livekit/react-native';
import { Track } from 'livekit-client';

import { SPIKE_LIVEKIT_URL, SPIKE_TOKEN } from './src/dev/spikeConfig';

async function requestCallPermissions(): Promise<boolean> {
  if (Platform.OS !== 'android') return true;
  const result = await PermissionsAndroid.requestMultiple([
    PermissionsAndroid.PERMISSIONS.CAMERA,
    PermissionsAndroid.PERMISSIONS.RECORD_AUDIO,
  ]);
  return Object.values(result).every((r) => r === PermissionsAndroid.RESULTS.GRANTED);
}

export default function App() {
  const [joined, setJoined] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // The audio session routes call audio correctly (earpiece/speaker, echo cancellation).
  useEffect(() => {
    AudioSession.startAudioSession();
    return () => {
      AudioSession.stopAudioSession();
    };
  }, []);

  const join = async () => {
    setError(null);
    if (await requestCallPermissions()) setJoined(true);
    else setError('Camera and microphone permission are needed for calls.');
  };

  if (!joined) {
    return (
      <View style={styles.center}>
        <StatusBar style="light" />
        <Text style={styles.title}>LandConnect</Text>
        <Text style={styles.subtitle}>Calling spike: room "spike"</Text>
        <Pressable style={styles.joinButton} onPress={join}>
          <Text style={styles.joinText}>Join video call</Text>
        </Pressable>
        {error && <Text style={styles.error}>{error}</Text>}
      </View>
    );
  }

  return (
    <LiveKitRoom
      serverUrl={SPIKE_LIVEKIT_URL}
      token={SPIKE_TOKEN}
      connect
      audio
      video
      options={{ adaptiveStream: { pixelDensity: 'screen' } }}
      onDisconnected={() => setJoined(false)}
      onError={(e) => setError(e.message)}
    >
      <StatusBar style="light" />
      <CallView />
    </LiveKitRoom>
  );
}

function CallView() {
  const room = useRoomContext();
  const state = useConnectionState();
  const { localParticipant, isMicrophoneEnabled, isCameraEnabled } = useLocalParticipant();
  const tracks = useTracks([Track.Source.Camera]);

  const remote = tracks.find((t) => !t.participant.isLocal);
  const local = tracks.find((t) => t.participant.isLocal);

  return (
    <View style={styles.call}>
      {remote && isTrackReference(remote) ? (
        <VideoTrack trackRef={remote} style={StyleSheet.absoluteFill} objectFit="cover" />
      ) : (
        <View style={styles.center}>
          <Text style={styles.subtitle}>
            {state === 'connected' ? 'Waiting for the other person…' : `Status: ${state}`}
          </Text>
        </View>
      )}

      {local && isTrackReference(local) && (
        <VideoTrack trackRef={local} style={styles.selfView} objectFit="cover" mirror />
      )}

      <View style={styles.controls}>
        <ControlButton
          label={isMicrophoneEnabled ? 'Mute' : 'Unmute'}
          onPress={() => localParticipant.setMicrophoneEnabled(!isMicrophoneEnabled)}
        />
        <ControlButton
          label={isCameraEnabled ? 'Cam off' : 'Cam on'}
          onPress={() => localParticipant.setCameraEnabled(!isCameraEnabled)}
        />
        <ControlButton label="End" danger onPress={() => room.disconnect()} />
      </View>
    </View>
  );
}

function ControlButton(props: { label: string; onPress: () => void; danger?: boolean }) {
  return (
    <Pressable
      onPress={props.onPress}
      style={[styles.controlButton, props.danger && { backgroundColor: '#E53935' }]}
    >
      <Text style={styles.controlText}>{props.label}</Text>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  center: { flex: 1, alignItems: 'center', justifyContent: 'center', backgroundColor: '#075E54', padding: 24 },
  title: { color: 'white', fontSize: 32, fontWeight: '700' },
  subtitle: { color: '#d8f3ec', fontSize: 16, marginTop: 8, textAlign: 'center' },
  joinButton: { marginTop: 32, backgroundColor: '#25D366', paddingHorizontal: 28, paddingVertical: 14, borderRadius: 28 },
  joinText: { color: 'white', fontSize: 18, fontWeight: '600' },
  error: { color: '#ffcdd2', marginTop: 16, textAlign: 'center' },
  call: { flex: 1, backgroundColor: '#111' },
  selfView: { position: 'absolute', top: 48, right: 16, width: 110, height: 160, borderRadius: 12, overflow: 'hidden' },
  controls: { position: 'absolute', bottom: 40, left: 0, right: 0, flexDirection: 'row', justifyContent: 'space-evenly' },
  controlButton: { backgroundColor: 'rgba(255,255,255,0.2)', paddingHorizontal: 18, paddingVertical: 14, borderRadius: 30 },
  controlText: { color: 'white', fontWeight: '600' },
});
